import 'package:cloud_firestore/cloud_firestore.dart';
class BusinessProfileService { final FirebaseFirestore db; BusinessProfileService({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance; Future<void> save(String uid,Map<String,dynamic> profile) async {const a={'name','description','phone','website','address','location','hours','category','photoUrl','isBusiness'};final p=<String,dynamic>{};for(final e in profile.entries){if(a.contains(e.key))p[e.key]=e.value;}p['updatedAt']=FieldValue.serverTimestamp();await db.collection('businessProfiles').doc(uid).set(p,SetOptions(merge:true));} }